def backup(path):
    if not path.exists():
        return
    BACKUP_DIR.mkdir(parents=True, exist_ok=True)
    dst = BACKUP_DIR / path.name
    if not dst.exists():
        shutil.copyfile(path, dst)
        dst.touch()
        print("[BACKUP]", dst.relative_to(ROOT))

# Ensure our proven guitar voicegroup exists.
VG_FILE.parent.mkdir(parents=True, exist_ok=True)
if not VG_FILE.exists():
    VG_FILE.write_text(VOICEGROUP_TEXT, encoding="utf-8")
    VG_FILE.touch()
    print("[WRITE]", VG_FILE.relative_to(ROOT))
else:
    vg = VG_FILE.read_text(encoding="utf-8")
    if "DirectSoundWaveData_sd90_classical_overdrive_guitar" not in vg:
        backup(VG_FILE)
        VG_FILE.write_text(VOICEGROUP_TEXT, encoding="utf-8")
        VG_FILE.touch()
        print("[PATCH]", VG_FILE.relative_to(ROOT))

if VG_INC.exists():
    text = VG_INC.read_text(encoding="utf-8")
    line = '.include "sound/voicegroups/hlw_indie_guitar.inc"'
    if line not in text:
        backup(VG_INC)
        if text and not text.endswith("\n"):
            text += "\n"
        text += line + "\n"
        VG_INC.write_text(text, encoding="utf-8")
        VG_INC.touch()
        print("[PATCH]", VG_INC.relative_to(ROOT))

# Replace only the four corrected MIDIs.
for name, payload in DATA.items():
    raw = base64.b64decode(payload)
    if hashlib.sha256(raw).hexdigest() != HASHES[name]:
        raise SystemExit("ERRO INTERNO: hash invalido para " + name)

    dst = MIDI_DIR / name
    backup(dst)
    dst.write_bytes(raw)
    dst.touch()
    print("[WRITE]", dst.relative_to(ROOT))

    asm = dst.with_suffix(".s")
    if asm.exists():
        asm.unlink()
        print("[DELETE]", asm.relative_to(ROOT))

    for obj in ROOT.glob("build/*/sound/songs/midi/" + dst.stem + ".o"):
        obj.unlink()
        print("[DELETE]", obj.relative_to(ROOT))

# Ensure the four tracks use the electric-guitar voicegroup.
if MIDI_CFG.exists():
    cfg = MIDI_CFG.read_text(encoding="utf-8")
    original = cfg
    for name, volume in CFG.items():
        desired = f"{name}: -E -R35 -G_hlw_indie_guitar -V{volume:03d}"
        pattern = re.compile(r"^" + re.escape(name) + r":.*$", re.MULTILINE)
        if pattern.search(cfg):
            cfg = pattern.sub(desired, cfg)
        else:
            if cfg and not cfg.endswith("\n"):
                cfg += "\n"
            cfg += desired + "\n"
    if cfg != original:
        backup(MIDI_CFG)
        MIDI_CFG.write_text(cfg, encoding="utf-8")
        MIDI_CFG.touch()
        print("[PATCH]", MIDI_CFG.relative_to(ROOT))

